'use client';
import { cx } from '../lib/cx';
import { useControllable } from '../lib/hooks';
import { Icon } from '../lib/icons';
import { Bars, Dot, Fold, Radar, Spin, Swap, Think } from '../lib/motion';
import '../designme.css';
import './step-loader.css';

export interface Step {
  /** Shown while the step runs, like "Reading Figma frames" */
  label: string;
  /** Shown once it is done, like "Read 4 frames". Falls back to label */
  done?: string;
}

export type StepLoaderGlyph = 'radar' | 'dots' | 'ring' | 'bars';

export interface StepLoaderProps {
  steps: Step[];
  /** Index of the step running now. steps.length (or more) means every step is done */
  current: number;
  /** The loader beside the running step */
  loader?: StepLoaderGlyph;
  /** Label once every step is done */
  doneLabel?: string;
  /** Whether the list of every step is open. Leave it out to let the row toggle it */
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  className?: string;
}

const Loader = ({ kind }: { kind: StepLoaderGlyph }) =>
  kind === 'dots' ? <Think /> : kind === 'ring' ? <Spin /> : kind === 'bars' ? <Bars /> : <Radar />;

/** Named steps with a progress track. Click the row to see every step. */
export function StepLoader({ steps, current, loader = 'radar', doneLabel = 'Ready for review', open, defaultOpen = false, onOpenChange, className }: StepLoaderProps) {
  const [isOpen, setOpen] = useControllable(open, defaultOpen, onOpenChange);
  const n = steps.length, done = current >= n, at = Math.min(current, n - 1);
  return (
    <div data-dm="" className={cx('dm-stl', className)} style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 10 }}>
      <button type="button" className="dm-stl-row" aria-expanded={isOpen} onClick={() => setOpen(!isOpen)}>
        <span className="dm-stl-g">{done ? <span style={{ color: 'var(--dm-ok)', display: 'grid' }}><Icon name="ok" /></span> : <Loader kind={loader} />}</span>
        <span className="dm-stl-t"><Swap className={cx('dm-stl-lab', !done && 'dm-shim')}>{done ? doneLabel : steps[at].label}</Swap></span>
        <Swap className="dm-stl-n dm-num">{`${done ? n : at + 1}/${n}`}</Swap>
        <Icon name="chev-d" size="xs" className="dm-stl-chev" />
      </button>
      <div className="dm-stl-track" role="progressbar" aria-valuemin={0} aria-valuemax={n} aria-valuenow={done ? n : at}>
        {steps.map((_, i) => <i key={i} className={cx((done || i < current) && 'dm-on', !done && i === current && 'dm-run')} />)}
      </div>
      <Fold open={isOpen} className="dm-stl-fold">
        <ol className="dm-stl-list">
          {steps.map((s, i) => {
            const finished = done || i < current, running = !done && i === current;
            return (
              <li key={i} className={cx(finished && 'dm-done', running && 'dm-run')}>
                <span className="dm-g">{finished ? <span style={{ color: 'var(--dm-ok)', display: 'grid' }}><Icon name="check" size="xs" /></span> : running ? <Loader kind={loader} /> : <Dot color="var(--dm-faint)" />}</span>
                {finished ? s.done ?? s.label : s.label}
              </li>
            );
          })}
        </ol>
      </Fold>
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Step loader ---------- */
.dm-stl .dm-dm-main{gap:10px}
.dm-stl-row{display:flex;align-items:center;gap:10px;background:var(--dm-surface);border-radius:var(--dm-r-pill);box-shadow:var(--dm-shadow);height:40px;padding:0 14px 0 13px;font-size:13.5px;min-width:250px;transition:box-shadow .3s}
@media (hover:hover) and (pointer:fine){.dm-stl-row:hover{box-shadow:var(--dm-shadow-pop)}}
.dm-stl-g{width:16px;display:grid;place-items:center;color:var(--dm-fg)}
.dm-stl-t{flex:1;text-align:left}
.dm-stl-n{color:var(--dm-muted);font-size:12.5px}
.dm-stl-chev{color:var(--dm-muted);transition:transform .4s var(--dm-ease)}
.dm-stl-row[aria-expanded="true"] .dm-stl-chev{transform:rotate(180deg)}
.dm-stl-track{display:flex;gap:var(--dm-s-1);width:250px}
.dm-stl-track i{flex:1;height:3px;border-radius:2px;background:var(--dm-line);position:relative;overflow:hidden}
.dm-stl-track i::after{content:"";position:absolute;inset:0;background:var(--dm-accent-mark,var(--dm-accent));transform:scaleX(0);transform-origin:left;transition:transform .9s var(--dm-ease)}
.dm-stl-track i.dm-on::after{transform:scaleX(1)}
.dm-stl-track i.dm-run::after{transform:scaleX(.45);transition-duration:2.2s}
.dm-stl-fold{width:250px}
.dm-stl-fold>div{margin-inline:-16px;padding-inline:var(--dm-s-4)}
.dm-stl-list{list-style:none;margin:6px 0 18px;padding:6px;background:var(--dm-surface);border-radius:calc(14px * var(--dm-rk));box-shadow:var(--dm-shadow)}
.dm-stl-list li{display:flex;align-items:center;gap:9px;padding:6px var(--dm-s-2);font-size:13px;color:var(--dm-muted)}
.dm-stl-list li.dm-done{color:var(--dm-fg2)}.dm-stl-list li.dm-run{color:var(--dm-fg)}
.dm-stl-list li .dm-g{width:14px;display:grid;place-items:center}
.dm-bars3{display:inline-flex;gap:2px;align-items:center;height:12px}
.dm-bars3 i{width:2.5px;height:100%;border-radius:2px;background:currentColor;animation:dm-b3 .9s var(--dm-ease-io) infinite}
.dm-bars3 i:nth-child(2){animation-delay:.15s}.dm-bars3 i:nth-child(3){animation-delay:.3s}
@keyframes dm-b3{0%,100%{transform:scaleY(.35)}50%{transform:scaleY(1)}}
